UPDATE zangraf_products p SET data=jsonb_set(jsonb_set(jsonb_set(jsonb_set(p.data,'{name}',value->'next'->'name'),'{category}',value->'next'->'category'),'{description}',value->'next'->'description'),'{options,covers}',value->'next'->'options'->'covers'),updated_at=now()
FROM source WHERE EXISTS(SELECT 1 FROM zg_cover_import_once) AND p.id=value->>'id'
AND p.data->'name'=value->'previous'->'name' AND p.data->'category'=value->'previous'->'category'
AND p.data->'description'=value->'previous'->'description' AND p.data->'options'->'covers'=value->'previous'->'options'->'covers';
