INSERT INTO zangraf_settings(key,data)
SELECT 'diagrammer-model:'||(value->>'id'),value FROM source
WHERE EXISTS(SELECT 1 FROM zg_cover_import_once)
AND (NOT EXISTS(SELECT 1 FROM zangraf_settings WHERE key='catalog-real-photos-v1') OR EXISTS(SELECT 1 FROM zangraf_products p WHERE p.id=value->>'productId' AND p.data->'options'->'sizes'=jsonb_build_array(value->>'sizeLabel')))
AND NOT EXISTS(SELECT 1 FROM zangraf_settings s WHERE s.key LIKE 'diagrammer-model:%' AND s.data->>'productId'=value->>'productId' AND s.data->>'sizeLabel'=value->>'sizeLabel')
ON CONFLICT(key) DO NOTHING;
COMMIT;
